const HOUR: i64 = 3600;
const DAY: i64 = 86_400;
/// Letters and digits without the ones that are easy to misread.
const ALPHABET: &[u8] = b"abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";

const CATEGORIES: [&str; 4] = ["Web", "Crypto", "Forensics", "Misc"];

/// A sample challenge: one flag, or several questions that share the points.
enum Kind {
    Flag {
        flag: &'static str,
        scoring: Scoring,
        hint: Option<(&'static str, i64)>,
    },
    Multi {
        points: i64,
        /// (question, answer, points)
        items: &'static [(&'static str, &'static str, i64)],
        /// (file name, contents) players can download.
        file: Option<(&'static str, &'static str)>,
    },
}

struct Spec {
    category: usize,
    title: &'static str,
    about: &'static str,
    kind: Kind,
}

const fn fixed(points: i64) -> Scoring {
    Scoring::Static { points }
}

