/// What was created for a challenge, so players can be scripted to answer it.
struct Built {
    id: i64,
    flag: Option<&'static str>,
    /// (item id, answer)
    items: Vec<(i64, &'static str)>,
}

struct Seed {
    state: AppState,
    clock: Arc<AtomicI64>,
}

impl Seed {
    fn new(state: &AppState) -> Self {
        let clock = Arc::new(AtomicI64::new(now()));
        let shared = Arc::clone(&clock);
        Self {
            state: state
                .clone()
                .with_clock(Arc::new(move || shared.load(Ordering::SeqCst))),
            clock,
        }
    }

    fn at(&self, t: i64) {
        self.clock.store(t, Ordering::SeqCst);
    }

    fn pool(&self) -> &SqlitePool {
        &self.state.pool
    }
}

#[derive(Serialize)]
pub struct Account {
    pub username: String,
    pub role: &'static str,
    pub about: &'static str,
}

#[derive(Serialize)]
pub struct Report {
    pub added: usize,
    pub password: String,
    pub accounts: Vec<Account>,
}

fn generate_password() -> String {
    (0..16)
        .map(|_| ALPHABET[usize::from(rand::random::<u8>()) % ALPHABET.len()] as char)
        .collect()
}

fn display(username: &str) -> String {
    let name = username.strip_prefix("demo-").unwrap_or(username);
    let mut chars = name.chars();
    chars.next().map_or_else(String::new, |c| {
        c.to_uppercase().collect::<String>() + chars.as_str()
    })
}

async fn ensure_user(
    pool: &SqlitePool,
    username: &str,
    role: Role,
    hash: &str,
    about: &str,
    at: i64,
) -> Result<i64, ApiError> {
    let id = match users::by_username(pool, username).await? {
        Some(user) => user.id,
        None => {
            users::create(
                pool,
                username,
                Some(&format!("{username}@demo.kymo.test")),
                hash,
                at,
            )
            .await?
        }
    };
    users::set_password(pool, id, hash).await?;
    users::moderate(pool, id, Some(role), None).await?;
    users::update_profile(pool, id, Some(&display(username)), Some(about)).await?;
    Ok(id)
}

struct EventSpec {
    name: &'static str,
    about: &'static str,
    mode: Mode,
    /// Seconds from now.
    starts: i64,
    ends: i64,
    policy: RegistrationPolicy,
    closes: Option<i64>,
    team_min: i64,
}

/// Inserts the event row (a draft) and returns its id.
async fn insert_event(pool: &SqlitePool, spec: &EventSpec, at: i64) -> Result<i64, ApiError> {
    let fields = EventFields {
        kind: EventKind::Jeopardy,
        mode: spec.mode,
        name: spec.name.to_owned(),
        description: spec.about.to_owned(),
        registration_opens: Some(at + spec.starts - 5 * DAY),
        registration_closes: spec.closes.map(|c| at + c),
        starts_at: Some(at + spec.starts),
        ends_at: Some(at + spec.ends),
        scoreboard_public: true,
        team_min: spec.team_min,
        team_max: 4,
        allow_invites: true,
        roster_locked: true,
        registration_policy: spec.policy,
    };
    let mut tx = db::begin_write(pool).await?;
    let id = event_store::insert(&mut tx, &fields, &slugify(spec.name), at).await?;
    tx.commit().await?;
    Ok(id)
}

/// Categories and the chosen sample challenges of an event, published. `fixed_only` turns
/// dynamic scoring into fixed points, as a tournament requires.
async fn add_challenges(
    pool: &SqlitePool,
    event_id: i64,
    picks: &[usize],
    fixed_only: bool,
    at: i64,
) -> Result<Vec<Built>, ApiError> {
    let mut categories = Vec::new();
    for (position, name) in CATEGORIES.iter().enumerate() {
        categories
            .push(challenge_store::category_insert(pool, event_id, name, position as i64).await?);
    }
    let mut built = Vec::new();
    for (position, index) in picks.iter().enumerate() {
        let spec = &SPECS[*index];
        let (scoring, flag, kind) = match &spec.kind {
            Kind::Flag { flag, scoring, .. } => (
                if fixed_only { fixed(100) } else { *scoring },
                *flag,
                "flag",
            ),
            Kind::Multi { points, .. } => (fixed(*points), "dfir", "dfir"),
        };
        let id = challenge_store::challenge_insert(
            pool,
            event_id,
            &challenge_store::ChallengeFields {
                category_id: categories[spec.category],
                title: spec.title.to_owned(),
                description: spec.about.to_owned(),
                scoring,
                flag: FlagSpec::Static {
                    value: flag.to_owned(),
                },
                flag_prefix: if kind == "flag" {
                    "KYMO{".into()
                } else {
                    String::new()
                },
                flag_suffix: if kind == "flag" {
                    "}".into()
                } else {
                    String::new()
                },
                case_sensitive: true,
                max_attempts: None,
                release_at: None,
                retire_at: None,
                position: position as i64,
                requires_instance: false,
                instance_config: None,
                kind: kind.into(),
            },
            at,
        )
        .await?;
        let mut items = Vec::new();
        match &spec.kind {
            Kind::Flag { hint, .. } => {
                if let (Some((text, cost)), false) = (hint, fixed_only) {
                    challenge_store::hint_insert(pool, id, text, *cost, 0).await?;
                }
            }
            Kind::Multi {
                items: questions,
                file,
                ..
            } => {
                let fields: Vec<ItemFields> = questions
                    .iter()
                    .map(|(q, a, p)| ItemFields {
                        question: (*q).to_owned(),
                        answer: FlagSpec::Static {
                            value: (*a).to_owned(),
                        },
                        case_sensitive: false,
                        points: *p,
                        max_attempts: Some(5),
                    })
                    .collect();
                dstore::replace_items(pool, id, &fields).await?;
                let stored = dstore::items(pool, id).await?;
                items = stored
                    .iter()
                    .zip(questions.iter())
                    .map(|(row, (_, a, _))| (row.id, *a))
                    .collect();
                if let Some((name, body)) = file {
                    challenge_store::attachment_insert(
                        pool,
                        id,
                        name,
                        "text/plain",
                        body.as_bytes(),
                    )
                    .await?;
                }
            }
        }
        challenge_store::set_challenge_state(pool, id, "published").await?;
        built.push(Built {
            id,
            flag: matches!(spec.kind, Kind::Flag { .. }).then_some(flag),
            items,
        });
    }
    Ok(built)
}

/// Scripts a field of participants through an event: stronger (earlier) participants solve more
/// and sooner, some guess wrong first, multi-question challenges are answered partly, and a
/// few solves land late. `members[r]` are the accounts that can answer for participant `r`.
async fn play_event(
    seed: &Seed,
    slug: &str,
    built: &[Built],
    members: &[Vec<i64>],
    start: i64,
    horizon: i64,
) -> Result<(), ApiError> {
    let n = members.len().max(1);
    for (r, team) in members.iter().enumerate() {
        let threshold = 7 - (r * 6 / n) as i64;
        for (c, ch) in built.iter().enumerate() {
            if ((c * 5 + r * 3) % 7) as i64 >= threshold {
                continue;
            }
            let user = team[c % team.len()];
            let late = if (r + c) % 5 == 0 { 9000 } else { 0 };
            let t = (start + 600 + c as i64 * 1700 + r as i64 * 410 + late).min(horizon - 600);
            let ip = format!("192.0.2.{}", 10 + r);
            // The event's state is judged at the script's time, so move the clock first.
            seed.at(t - 60);
            let play = submit::play_context(&seed.state, slug, user).await?;
            let row = challenge_store::challenge_by_id(seed.pool(), ch.id).await?;
            if let Some(flag) = ch.flag {
                if (r + c) % 3 == 0 {
                    seed.at(t - 45);
                    submit::run(
                        &seed.state,
                        &play,
                        &row,
                        &Attempt {
                            user_id: user,
                            ip: ip.clone(),
                            flag: "KYMO{not_this_one}",
                        },
                    )
                    .await?;
                }
                seed.at(t);
                submit::run(
                    &seed.state,
                    &play,
                    &row,
                    &Attempt {
                        user_id: user,
                        ip: ip.clone(),
                        flag,
                    },
                )
                .await?;
            } else {
                let answered = ((r + c) % (ch.items.len() + 1)).max(usize::from(r < n / 2));
                for (k, (item, answer)) in ch.items.iter().take(answered).enumerate() {
                    let when = t + k as i64 * 95;
                    if k == 1 && (r + c) % 2 == 0 {
                        seed.at(when - 30);
                        submit::run_item(
                            &seed.state,
                            &play,
                            &row,
                            *item,
                            &Attempt {
                                user_id: user,
                                ip: ip.clone(),
                                flag: "not sure",
                            },
                        )
                        .await?;
                    }
                    seed.at(when);
                    submit::run_item(
                        &seed.state,
                        &play,
                        &row,
                        *item,
                        &Attempt {
                            user_id: user,
                            ip: ip.clone(),
                            flag: answer,
                        },
                    )
                    .await?;
                }
            }
        }
    }
    Ok(())
}

async fn register_all(
    pool: &SqlitePool,
    event_id: i64,
    users: &[i64],
    at: i64,
) -> Result<(), ApiError> {
    for (i, user) in users.iter().enumerate() {
        event_store::register(pool, event_id, Some(*user), None, at - HOUR + i as i64 * 60).await?;
    }
    Ok(())
}

/// A Jeopardy event that is live, played and (optionally) frozen.
#[allow(clippy::too_many_arguments)]
async fn live_event(
    seed: &Seed,
    spec: &EventSpec,
    picks: &[usize],
    players: &[i64],
    freeze: Option<i64>,
    final_state: EventState,
) -> Result<i64, ApiError> {
    let at = now();
    let pool = seed.pool();
    let id = insert_event(pool, spec, at).await?;
    let built = add_challenges(pool, id, picks, false, at + spec.starts - DAY).await?;
    register_all(pool, id, players, at + spec.starts).await?;
    let slug = slugify(spec.name);
    event_store::set_state(pool, id, EventState::Live, at + spec.starts).await?;
    if let Some(offset) = freeze {
        jeopardy_store::save_settings(
            pool,
            id,
            &JeopardySettings {
                freeze_at: Some(at + offset),
                ..JeopardySettings::default()
            },
        )
        .await?;
    }
    let horizon = (at).min(at + spec.ends);
    let members: Vec<Vec<i64>> = players.iter().map(|p| vec![*p]).collect();
    play_event(seed, &slug, &built, &members, at + spec.starts, horizon).await?;
    seed.at(at);
    if final_state != EventState::Live {
        let when = if final_state == EventState::Ended {
            at + spec.ends
        } else {
            at
        };
        event_store::set_state(pool, id, final_state, when).await?;
    }
    Ok(id)
}

async fn team_event(
    seed: &Seed,
    spec: &EventSpec,
    picks: &[usize],
    teams: &[(i64, Vec<i64>)],
) -> Result<i64, ApiError> {
    let at = now();
    let pool = seed.pool();
    let id = insert_event(pool, spec, at).await?;
    let built = add_challenges(pool, id, picks, false, at + spec.starts - DAY).await?;
    for (i, (team, _)) in teams.iter().enumerate() {
        event_store::register(
            pool,
            id,
            None,
            Some(*team),
            at + spec.starts - HOUR + i as i64 * 90,
        )
        .await?;
    }
    event_store::set_state(pool, id, EventState::Live, at + spec.starts).await?;
    let members: Vec<Vec<i64>> = teams.iter().map(|(_, m)| m.clone()).collect();
    play_event(
        seed,
        &slugify(spec.name),
        &built,
        &members,
        at + spec.starts,
        at,
    )
    .await?;
    seed.at(at);
    Ok(id)
}

// Tournaments decided by challenges.

struct Duel {
    tournament: i64,
    slug: String,
    event: i64,
    built: Vec<Built>,
}

#[allow(clippy::too_many_arguments)]
async fn duel_tournament(
    seed: &Seed,
    name: &str,
    format: Format,
    mode: Mode,
    assignment: kymo_duel::Assignment,
    count: u8,
    limit: Option<i64>,
    picks: &[usize],
    solo: &[i64],
    teams: &[(i64, Vec<i64>)],
) -> Result<Duel, ApiError> {
    let at = now() - 6 * HOUR;
    seed.at(at);
    let pool = seed.pool();
    let slug = slugify(name);
    let tid = db::create(
        pool,
        NewTournament {
            name,
            slug: &slug,
            format,
            third_place: false,
            groups: 2,
            advance: 2,
            rounds: 0,
            best_of: 1,
        },
    )
    .await?;
    let t = db::get(pool, tid).await?;
    let event = t.event_id.ok_or(ApiError::Internal)?;
    let row = event_store::by_id(pool, event).await?;
    let mut fields = EventFields::from(&row);
    fields.mode = mode;
    event_store::update(pool, event, &fields).await?;
    event_store::set_state(pool, event, EventState::RegistrationOpen, at).await?;
    dstore::save_settings(
        pool,
        tid,
        &ChallengeSettings {
            assignment,
            solo: count,
            team: count,
            seed: 11,
            time_limit: limit,
        },
    )
    .await?;
    let built = add_challenges(pool, event, picks, true, at).await?;
    for (i, user) in solo.iter().enumerate() {
        event_store::register(pool, event, Some(*user), None, at + i as i64 * 60).await?;
    }
    for (i, (team, _)) in teams.iter().enumerate() {
        event_store::register(pool, event, None, Some(*team), at + i as i64 * 60).await?;
    }
    let filled = duel::fill_roster(&seed.state, tid).await?;
    let ids: Vec<u32> = filled.teams.iter().map(|x| x.id as u32).collect();
    let bracket = generate_with(
        &ids,
        format,
        Options {
            third_place: false,
            groups: 2,
            advance: 2,
            rounds: 0,
            best_of: 1,
        },
    )?;
    events::record_tournament_at(
        pool,
        tid,
        "started",
        serde_json::json!({ "teams": ids.len(), "format": format }),
        at + 3600,
    )
    .await?;
    db::save_bracket(pool, tid, Some(&bracket), Status::Live, at + 3600).await?;
    monitor_store::audit_from(
        pool,
        at,
        None,
        "admin",
        None,
        "tournament_challenges_set",
        "tournament",
        tid,
        "demo setup",
    )
    .await?;
    Ok(Duel {
        tournament: tid,
        slug,
        event,
        built,
    })
}

/// Answers some of a match's units for one side, from `t0`, one every 70 seconds.
/// Returns the time of the last answer. A finished match stops the script quietly.
async fn answer_units(
    seed: &Seed,
    d: &Duel,
    match_id: usize,
    accounts: &[i64],
    count: usize,
    wrong_first: bool,
    t0: i64,
) -> Result<i64, ApiError> {
    let t = db::get(seed.pool(), d.tournament).await?;
    let event = event_store::by_id(seed.pool(), d.event).await?;
    let assigned = duel::ensure_assigned(&seed.state, &t, &event, match_id).await?;
    let mut units: Vec<(i64, Option<i64>, &'static str)> = Vec::new();
    for id in assigned {
        if let Some(b) = d.built.iter().find(|b| b.id == id) {
            match b.flag {
                Some(flag) => units.push((id, None, flag)),
                None => units.extend(
                    b.items
                        .iter()
                        .map(|(item, answer)| (id, Some(*item), *answer)),
                ),
            }
        }
    }
    let mut last = t0;
    for (k, (challenge, item, answer)) in units.into_iter().take(count).enumerate() {
        let user = accounts[k % accounts.len()];
        let ip = format!("198.51.100.{}", 10 + k);
        if wrong_first && k == 0 {
            seed.at(last + 20);
            let _ = duel::submit(
                &seed.state,
                &d.slug,
                match_id,
                &duel::Submission {
                    user_id: user,
                    ip: &ip,
                    challenge_id: challenge,
                    item_id: item,
                    value: "wrong guess",
                },
            )
            .await;
        }
        last = t0 + 70 * (k as i64 + 1);
        seed.at(last);
        match duel::submit(
            &seed.state,
            &d.slug,
            match_id,
            &duel::Submission {
                user_id: user,
                ip: &ip,
                challenge_id: challenge,
                item_id: item,
                value: answer,
            },
        )
        .await
        {
            Ok(_) => {}
            Err(ApiError::Conflict(_)) => break,
            Err(e) => return Err(e),
        }
    }
    Ok(last)
}

/// Dates a decided match's activity entries at the script's time, so the ladder has a history.
async fn date_result(
    pool: &SqlitePool,
    tid: i64,
    match_id: usize,
    at: i64,
) -> Result<(), ApiError> {
    sqlx::query("UPDATE activity SET at = ? WHERE tournament_id = ? AND match_id = ? AND kind IN ('result', 'corrected')")
        .bind(at)
        .bind(tid)
        .bind(match_id as i64)
        .execute(pool)
        .await?;
    Ok(())
}

async fn side_accounts(
    pool: &SqlitePool,
    d: &Duel,
    match_id: usize,
    side: usize,
    mode: Mode,
    teams: &[(i64, Vec<i64>)],
) -> Result<Vec<i64>, ApiError> {
    let t = db::get(pool, d.tournament).await?;
    let id = duel::side_ids(t.bracket.as_ref().ok_or(ApiError::Internal)?, match_id)
        .ok_or(ApiError::Internal)?[side];
    let team = t
        .teams
        .iter()
        .find(|x| x.id == id)
        .ok_or(ApiError::Internal)?;
    Ok(match mode {
        Mode::Solo => vec![team.user_id.ok_or(ApiError::Internal)?],
        Mode::Team => teams
            .iter()
            .find(|(team_id, _)| Some(*team_id) == team.player_team_id)
            .map(|(_, members)| members.clone())
            .ok_or(ApiError::Internal)?,
    })
}

#[allow(clippy::too_many_arguments)]
async fn play_match(
    seed: &Seed,
    d: &Duel,
    mode: Mode,
    teams: &[(i64, Vec<i64>)],
    match_id: usize,
    counts: [usize; 2],
    close: bool,
    t0: i64,
) -> Result<(), ApiError> {
    let a = side_accounts(seed.pool(), d, match_id, 0, mode, teams).await?;
    let b = side_accounts(seed.pool(), d, match_id, 1, mode, teams).await?;
    let end_a = answer_units(
        seed,
        d,
        match_id,
        &a,
        counts[0],
        match_id.is_multiple_of(2),
        t0,
    )
    .await?;
    let end_b = answer_units(seed, d, match_id, &b, counts[1], false, end_a + 40).await?;
    let last = end_a.max(end_b);
    if close {
        seed.at(last + 30);
        duel::settle(&seed.state, d.tournament, match_id, true, None).await?;
    }
    let t = db::get(seed.pool(), d.tournament).await?;
    if t.bracket
        .as_ref()
        .is_some_and(|br| br.matches[match_id].is_played())
    {
        date_result(seed.pool(), d.tournament, match_id, last + 30).await?;
    }
    Ok(())
}

async fn absent(pool: &SqlitePool, name: &str) -> bool {
    event_store::by_slug(pool, &slugify(name)).await.is_err()
}

pub async fn seed_all(state: &AppState) -> Result<Report, ApiError> {
    let mut added = crate::demo::seed(&state.pool).await?;
    let seed = Seed::new(state);
    let pool = seed.pool();
    let at = now();
    let password = generate_password();
    let hash = crate::passwords::hash(password.clone()).await?;

    let mut accounts = Vec::new();
    for (name, role, about) in [
        ("demo-admin", Role::Admin, "Organizer: every permission."),
        ("demo-referee", Role::Referee, "Referee: records results."),
        (
            "demo-monitor",
            Role::Monitor,
            "Monitor: traffic, bans and the audit log.",
        ),
    ] {
        ensure_user(pool, name, role, &hash, about, at - 60 * DAY).await?;
        accounts.push(Account {
            username: name.into(),
            role: role.as_str(),
            about,
        });
    }
    let mut ids = Vec::new();
    for name in PLAYERS {
        let username = format!("demo-{name}");
        ids.push(
            ensure_user(
                pool,
                &username,
                Role::Player,
                &hash,
                "A sample player.",
                at - 60 * DAY,
            )
            .await?,
        );
        accounts.push(Account {
            username,
            role: "player",
            about: "Registered in the sample events and on a team.",
        });
    }
    let newbie = ensure_user(
        pool,
        "demo-newbie",
        Role::Player,
        &hash,
        "Has no events yet.",
        at - DAY,
    )
    .await?;
    accounts.push(Account {
        username: "demo-newbie".into(),
        role: "player",
        about: "Registered nowhere: sign in and join something.",
    });
    let late = ensure_user(
        pool,
        "demo-late",
        Role::Player,
        &hash,
        "Added by an organizer after sign-ups closed.",
        at - DAY,
    )
    .await?;
    accounts.push(Account {
        username: "demo-late".into(),
        role: "player",
        about: "Added to Forensics Weekend by an organizer.",
    });
    let removed = ensure_user(
        pool,
        "demo-removed",
        Role::Player,
        &hash,
        "Was removed from an event.",
        at - DAY,
    )
    .await?;
    accounts.push(Account {
        username: "demo-removed".into(),
        role: "player",
        about: "Registered, then removed by an organizer (see the audit log).",
    });
    let admin = users::by_username(pool, "demo-admin").await?.map(|u| u.id);

    // Player teams: four teams of three, owned by the first member.
    let mut teams: Vec<(i64, Vec<i64>)> = Vec::new();
    for (i, name) in ["Red Team", "Blue Team", "Green Team", "Gold Team"]
        .iter()
        .enumerate()
    {
        let members: Vec<i64> = ids[i * 3..i * 3 + 3].to_vec();
        let team = match sqlx::query_scalar::<_, i64>("SELECT id FROM player_team WHERE name = ?")
            .bind(*name)
            .fetch_optional(pool)
            .await?
        {
            Some(id) => id,
            None => {
                let row = team_store::create(pool, name, members[0], at - 30 * DAY).await?;
                for m in &members[1..] {
                    team_store::add_member(pool, row.id, *m, at - 30 * DAY).await?;
                }
                row.id
            }
        };
        teams.push((team, members));
    }

    // Jeopardy, solo: live, frozen scoreboard, every challenge type.
    if absent(pool, "Forensics Weekend").await {
        let spec = EventSpec {
            name: "Forensics Weekend",
            about: "Live and frozen: the public board stopped 90 minutes ago, staff still see it moving. Flags, dynamic points, hints and multi-question challenges with partial credit.",
            mode: Mode::Solo,
            starts: -8 * HOUR,
            ends: 16 * HOUR,
            policy: RegistrationPolicy::Manual,
            closes: None,
            team_min: 1,
        };
        let id = live_event(
            &seed,
            &spec,
            &[0, 1, 2, 3, 4, 5, 6, 7, 8],
            &ids[..12],
            Some(-90 * 60),
            EventState::Live,
        )
        .await?;
        event_store::register(pool, id, Some(late), None, at - 1800).await?;
        monitor_store::audit_from(
            pool,
            at - 1800,
            admin,
            "admin",
            None,
            "participant_added",
            "event",
            id,
            "player @demo-late (registration was closed)",
        )
        .await?;
        event_store::register(pool, id, Some(removed), None, at - 7200).await?;
        let rows = event_store::participants(pool, id).await?;
        if let Some(p) = rows.iter().find(|p| p.user_id == Some(removed)) {
            event_store::remove_participant(pool, id, p.id, at - 3600).await?;
            monitor_store::audit_from(
                pool,
                at - 3600,
                admin,
                "admin",
                None,
                "participant_removed",
                "event",
                id,
                "demo-removed (their submissions and results stay on record)",
            )
            .await?;
        }
        added += 1;
    }
    // Jeopardy, teams.
    if absent(pool, "Team Forensics Cup").await {
        let spec = EventSpec {
            name: "Team Forensics Cup",
            about: "A live team event: teammates answer for the same team, including the questions of multi-question challenges.",
            mode: Mode::Team,
            starts: -6 * HOUR,
            ends: 18 * HOUR,
            policy: RegistrationPolicy::AtStart,
            closes: None,
            team_min: 2,
        };
        team_event(&seed, &spec, &[0, 2, 4, 5, 6, 8], &teams).await?;
        added += 1;
    }
    // Lifecycle: started early, paused, registration closed by hand, ended.
    if absent(pool, "Early Bird CTF").await {
        let spec = EventSpec {
            name: "Early Bird CTF",
            about: "An organizer started this event ahead of its schedule; registration stays open until a closing time.",
            mode: Mode::Solo,
            starts: 2 * HOUR,
            ends: 26 * HOUR,
            policy: RegistrationPolicy::AtTime,
            closes: Some(90 * 60),
            team_min: 1,
        };
        let id = insert_event(pool, &spec, at).await?;
        add_challenges(pool, id, &[0, 7, 8], false, at).await?;
        register_all(pool, id, &ids[..4], at).await?;
        event_store::set_state(pool, id, EventState::Live, at).await?;
        added += 1;
    }
    if absent(pool, "Paused Practice").await {
        let spec = EventSpec {
            name: "Paused Practice",
            about: "Paused by an organizer: nothing can be submitted until it resumes.",
            mode: Mode::Solo,
            starts: -3 * HOUR,
            ends: 21 * HOUR,
            policy: RegistrationPolicy::AtStart,
            closes: None,
            team_min: 1,
        };
        live_event(
            &seed,
            &spec,
            &[0, 7, 8],
            &ids[..4],
            None,
            EventState::Paused,
        )
        .await?;
        added += 1;
    }
    if absent(pool, "Closed Registration Cup").await {
        let spec = EventSpec {
            name: "Closed Registration Cup",
            about: "Registration is open by schedule but an organizer closed it by hand.",
            mode: Mode::Solo,
            starts: 3 * DAY,
            ends: 4 * DAY,
            policy: RegistrationPolicy::Manual,
            closes: None,
            team_min: 1,
        };
        let id = insert_event(pool, &spec, at).await?;
        add_challenges(pool, id, &[0, 4], false, at).await?;
        register_all(pool, id, &ids[..2], at).await?;
        event_store::set_state(pool, id, EventState::RegistrationOpen, at).await?;
        sqlx::query("UPDATE event SET registration_closed = 1 WHERE id = ?")
            .bind(id)
            .execute(pool)
            .await?;
        added += 1;
    }
    if absent(pool, "Autumn Forensics").await {
        let spec = EventSpec {
            name: "Autumn Forensics",
            about: "A finished event with multi-question challenges: the final board and the score over time.",
            mode: Mode::Solo,
            starts: -20 * DAY,
            ends: -19 * DAY,
            policy: RegistrationPolicy::AtStart,
            closes: None,
            team_min: 1,
        };
        live_event(
            &seed,
            &spec,
            &[0, 3, 4, 5, 6, 8],
            &ids[..10],
            None,
            EventState::Ended,
        )
        .await?;
        added += 1;
    }

    // Tournaments decided by challenges.
    if db::get_by_slug(pool, &slugify("Duel Cup")).await.is_err() {
        let d = duel_tournament(
            &seed,
            "Duel Cup",
            Format::SingleElimination,
            Mode::Solo,
            kymo_duel::Assignment::PerMatch,
            2,
            None,
            &[0, 3, 4, 6, 8],
            &ids[..8],
            &[],
        )
        .await?;
        let t0 = now() - 4 * HOUR;
        // Tied scores, the player who finished first advances.
        play_match(&seed, &d, Mode::Solo, &[], 0, [9, 9], false, t0).await?;
        // One side far ahead, closed by an organizer.
        play_match(&seed, &d, Mode::Solo, &[], 1, [9, 1], true, t0 + 1800).await?;
        // Still being played.
        play_match(&seed, &d, Mode::Solo, &[], 2, [1, 0], false, now() - 600).await?;
        // Assigned, not started.
        let t = db::get(pool, d.tournament).await?;
        let event = event_store::by_id(pool, d.event).await?;
        duel::ensure_assigned(&seed.state, &t, &event, 3).await?;
        added += 1;
    }
    if db::get_by_slug(pool, &slugify("Team Duel Cup"))
        .await
        .is_err()
    {
        let d = duel_tournament(
            &seed,
            "Team Duel Cup",
            Format::SingleElimination,
            Mode::Team,
            kymo_duel::Assignment::PerRound,
            3,
            Some(HOUR),
            &[0, 3, 4, 5, 6, 8],
            &[],
            &teams,
        )
        .await?;
        play_match(
            &seed,
            &d,
            Mode::Team,
            &teams,
            0,
            [12, 5],
            true,
            now() - 3 * HOUR,
        )
        .await?;
        play_match(&seed, &d, Mode::Team, &teams, 1, [3, 2], false, now() - 900).await?;
        added += 1;
    }
    if db::get_by_slug(pool, &slugify("Challenge League"))
        .await
        .is_err()
    {
        let d = duel_tournament(
            &seed,
            "Challenge League",
            Format::RoundRobin,
            Mode::Solo,
            kymo_duel::Assignment::Manual,
            2,
            None,
            &[0, 4, 6, 8],
            &ids[..4],
            &[],
        )
        .await?;
        let published: Vec<i64> = d.built.iter().map(|b| b.id).collect();
        for m in 0..3usize {
            dstore::assign(
                pool,
                d.tournament,
                m as i64,
                &[published[m % 2], published[2 + m % 2]],
            )
            .await?;
        }
        play_match(
            &seed,
            &d,
            Mode::Solo,
            &[],
            0,
            [9, 9],
            false,
            now() - 5 * HOUR,
        )
        .await?;
        play_match(
            &seed,
            &d,
            Mode::Solo,
            &[],
            1,
            [9, 2],
            true,
            now() - 3 * HOUR,
        )
        .await?;
        added += 1;
    }
    let _ = newbie;
    Ok(Report {
        added,
        password,
        accounts,
    })
}
